programs.haiku:
"""Layer 15 MLP down-projection, component 201.

What it does: it writes a "this word is not finished / is unusual" signal into the
residual stream. Its write direction promotes word-continuation pieces (on its own it
favours pieces like "ities", "etical", "chemy"), so it is strongest on short, rare or
unfinished word pieces (a name fragment such as " Sh" or " U", a technical stem such as
" logarith") and weakest on common, complete words and on closing punctuation. The
end-of-text token is very high, and the first token of each document is zero.

The program predicts that from the token text alone:
- end-of-text: 10; other special or replacement-character tokens: about 4;
- letters: a linear function of how rare the word is (wordfreq Zipf frequency: about 6
  for "the", 0 for a non-word) and of its length in letters, with a separate line for each
  of four classes (leading space or not, capitalised or not);
- digits: about 2 for the first digit of a number and 0.7 for a digit inside one;
  spaces and CJK characters: about 1.4; punctuation: about 0.6;
- the first token of each document: 0.
"""

import re

from wordfreq import zipf_frequency

READS = ()

# (leading space, capitalised): (intercept, slope per Zipf unit, slope per letter)
LETTER = {
    (True, True): (9.2, -0.87, -0.47),
    (True, False): (5.8, -0.63, -0.26),
    (False, True): (6.0, -0.47, -0.38),
    (False, False): (2.9, 0.05, -0.27),
}
LETTERS = re.compile(r"[A-Za-z]+")
CJK = re.compile(r"[\u3040-\u30ff\u3400-\u9fff\uac00-\ud7af]")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0  # first token of a document
    if token == "<|endoftext|>":
        return carry, 10.0
    if token.startswith("<|") or "\ufffd" in token:
        return carry, 4.0
    core = token.strip()
    if LETTERS.fullmatch(core):
        key = (token[:1] == " ", core[0].isupper())
        intercept, per_zipf, per_letter = LETTER[key]
        rarity = zipf_frequency(core.lower(), "en")  # about 6 for "the", 0 for a non-word
        return carry, intercept + per_zipf * rarity + per_letter * len(core)
    if re.fullmatch(r"\d", core):
        inside = re.fullmatch(r"\d", prefix.token_strings[-2].strip()) is not None
        return carry, 0.7 if inside else 2.0  # a digit that starts a number vs one inside it
    if CJK.search(core) or not core:
        return carry, 1.4
    if re.fullmatch(r"[^\w\s]+", core):
        return carry, 0.6
    return carry, 2.0

"""Predict layers.15 MLP unit 204 (its down_proj component 204) from the words around it.

What this component is: it reads essentially one MLP hidden unit of layer 15 (its input
direction is almost entirely that unit), so its activation is that unit's signed value.
That unit is large and positive on words that set up or restate the conditions of a
word problem ("problem", "question", "says", "states", "given", "since", "But"), and on
the word right after them, and it is mildly negative on punctuation, markup and code.

This program is a lexical guess, not the unit's computation. It predicts:
  - about +0.5 on "since" or "given", and +0.35 on "problem", "question", "says",
    "states", "asks", and +0.3 on "but";
  - about +0.05 on a weaker logic connective ("if", "so", "however", "because", ...);
  - about +0.3 on an ordinary word right after a premise word, and +1.5 on a premise
    word right after another one;
  - about -0.07 on punctuation, whitespace, brackets and markup;
  - about -0.04 on everything else.

Those values are rough mean activations of each class on training rows. Only the current
and previous token are read, so it is stateless.
"""

import re
from collections.abc import Mapping

READS: tuple[str, ...] = ()

STRONG = {"since", "given"}
PREMISE = {"problem", "question", "says", "states", "asks", "but"}
CONNECTIVE = {
    "if", "so", "now", "because", "however", "yet", "although", "thus", "therefore",
    "wait", "despite", "expects", "specifies", "supposed", "required", "asking",
    "statement", "stated",
}
MARKUP = re.compile(r"[\s.:)}\]{\\`\"',\[(|\-+=*^$²³≤≥⇒]*")


def _word(token: str) -> str:
    return token.strip().lower()


def _is_premise(word: str) -> bool:
    return word in STRONG or word in PREMISE


def step(carry, prefix, upstream: Mapping):
    token = prefix.token_strings[-1]
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    previous = _word(prefix.token_strings[-2]) if same_doc else ""
    word = _word(token)
    if _is_premise(word):
        value = 1.5 if _is_premise(previous) else (0.5 if word in STRONG else 0.35)
    elif word in CONNECTIVE:
        value = 0.05
    elif _is_premise(previous):
        value = 0.3
    elif MARKUP.fullmatch(token):
        value = -0.07
    else:
        value = -0.04
    return carry, value

"""Component layers.15.mlp.down_proj:208 as a punctuation detector.

The component's activation is signed. Ordinary letters and digits sit slightly below zero,
and the component is clearly positive on symbols that join, close or separate pieces of
text. This program predicts that pattern from the current token and the one or two before
it, with no model in it:

- Letters and digits: a small negative constant (-0.1).
- Spaces and newlines: a small positive constant.
- Symbols, by kind, each at its typical value on sample text:
  - separators: commas (0.8), periods (0.5), semicolons, colons;
  - joiners: hyphens and slashes (the strongest, about 1 to 1.4), '::', '_', '->';
  - possessive 's and ’s (about 1.5);
  - closing quotes and brackets (about 0.7 to 2), opening quotes and brackets (about 0.3 to 0.6);
  - CJK particles 的 and の (about 1.8);
  - '=' (zero), and any other symbol at about 0.17.
- Two context rules, for the commas and periods that carry most of the variance:
  - a comma right after a sentence-opening word ("So,", "Then,", "Now,") is high (1.75);
  - a period after an initial or abbreviation ("J.", "St.", "Inc.") is high (1.5), while a
    period or comma after a number is low.

Those values are the means measured on sample text, not fitted weights. The program
explains about 9% of the activation's variance on eval. It misses the spread among letter
tokens (their spread is about 0.8 and is not explained by token identity or simple word
classes) and the wide spread within each symbol.
"""

import re

READS = ()

LETTERS = re.compile(r"\s*[A-Za-z]+")
DIGITS = re.compile(r"\s*[0-9]+")
ABBREVIATION = re.compile(r"\s*[A-Z][A-Za-z]{0,3}")

SEPARATORS = {",": 0.8, "，": 0.75, "、": 1.1, ".": 0.5, ";": 0.4, ":": 0.1}
JOINERS = {"-": 1.1, "–": 0.85, "/": 1.4, "::": 1.6, "_": 0.6, "__": 1.0, "->": 0.7, "*": 0.8}
POSSESSIVE = {"'s": 1.5, "’s": 1.6, "'t": 0.0}
QUOTES = {'"': 0.25, "'": 0.6, "“": -0.3, "”": 1.75, "’": 2.0, "`": 0.5, '",': 1.0}
BRACKETS = {"(": 0.5, ")": 0.7, "[": 0.5, "]": 1.0, "{": 0.35, "}": 0.4, '{"': 1.2}
CJK_PARTICLES = {"的": 1.85, "の": 1.8}
SYMBOLS = {**SEPARATORS, **JOINERS, **POSSESSIVE, **QUOTES, **BRACKETS, **CJK_PARTICLES, "=": 0.0}


def step(carry, prefix, upstream):
    t = prefix.position
    cur = prefix.token_strings[-1].strip()
    same = lambda k: t - k >= 0 and prefix.document_ids[t - k] == prefix.document_ids[t]
    prev = prefix.token_strings[-2] if same(1) else None
    prev2 = prefix.token_strings[-3] if same(2) else None
    if cur == ",":
        # a comma right after a word that opens a sentence ("So," "Then," "Now,")
        opens_sentence = prev2 is None or prev2.strip() in (".", "!", "?") or "\n" in prev2
        if prev and LETTERS.fullmatch(prev) and opens_sentence:
            return carry, 1.75
        if prev and DIGITS.fullmatch(prev):
            return carry, 0.9
    if cur == "." and prev:
        if ABBREVIATION.fullmatch(prev):
            return carry, 1.5  # after an initial or abbreviation: "J." "St." "Inc."
        if DIGITS.fullmatch(prev):
            return carry, 0.25  # after a number
    if cur in SYMBOLS:
        return carry, SYMBOLS[cur]
    if cur == "":
        return carry, 0.17  # whitespace
    if LETTERS.fullmatch(cur) or DIGITS.fullmatch(cur):
        return carry, -0.1
    return carry, 0.17  # any other symbol

"""Layer 15, MLP down-projection, component 213: a casual-idiom detector.

The component is mostly negative. It goes strongly negative on the word of a casual,
idiomatic English phrase, the verb or particle of a phrasal verb or everyday expression
("get", "take", "go with", "come up", "hit it big", "pull something off"), and on
spoken-style filler ("Hmm", "Wait"). It is weakly positive on formal, biographical wording
("born", "died", "graduated", "would", "may"), and near zero elsewhere.

This program reads only the current word and the word before it, and predicts the value
by word class. It captures a small share of the variance: the big negative spikes are
spread over many words and depend on context a word list cannot see.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

FILLER = {"hmm", "wait"}
# Verbs that carry idiomatic, everyday senses (get it, take on, go with, think, try, pull off).
COLLOQUIAL_VERBS = {
    "get", "gets", "got", "getting", "take", "takes", "took", "taking",
    "go", "goes", "going", "went", "gone", "think", "try", "tries", "trying",
    "hit", "hits", "hitting", "miss", "missed", "pull", "come", "comes", "came",
    "coming", "work", "works", "working", "handle", "do", "does", "doing", "did",
    "check", "grab", "beat", "stick", "stuck", "mess", "messed", "deal", "figure",
    "see", "make", "put", "bring", "brought", "keep", "hang", "blow", "knock", "throw",
}
# Casual, evaluative or vague words that go with the idioms.
CASUAL_WORDS = {
    "yes", "okay", "ok", "nice", "great", "good", "big", "deal", "stuff", "thing",
    "things", "something", "everything", "anything", "trick", "bit", "way", "mistake",
    "chance", "luck", "idea", "enough", "too", "tough", "hard", "crazy", "skinny", "right",
}
# Particles and pronouns that complete a phrasal verb ("on", "up", "out", "off", "it").
PARTICLES = {
    "on", "up", "out", "off", "down", "through", "at", "it", "me", "over", "away",
    "around", "back", "them", "all",
}
# Formal or biographical wording, weakly positive.
FORMAL_WORDS = {
    "born", "birth", "died", "graduated", "married", "lived", "will", "would", "may",
    "merely", "originally", "granted", "normally",
}


def step(carry, prefix, upstream: Mapping):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if word in FILLER:
        value = -1.5
    elif word in COLLOQUIAL_VERBS or word in CASUAL_WORDS:
        value = -0.9
    elif word in PARTICLES:
        value = -1.9 if prev in COLLOQUIAL_VERBS else -0.4
    elif word in FORMAL_WORDS:
        value = 0.4
    else:
        value = 0.0
    return carry, float(value)

"""A dip on words about how much something needs, costs or takes.

Layer 15's MLP unit 221 dominates this component. When its activation is negative, the
model's next-token guess shifts toward cost and requirement words ("cost", "required",
"need"). The activation is most negative on:

- requirement words themselves: "required", "need", "requires", "take", "must";
- quantity and size words: "much", "more", "little", "number", "time", "length";
- the word right after a cue such as "need", "without", "takes", "how", "number", "total":
  the slot where an amount or a requirement is expected ("without [extra] cost");
- "to" after "has", "have", "had", "got", "hard" or "easy", as in "has [to] do" or
  "hard [to] change", where something is necessary or effortful.

Everything else sits near zero, which is where most of the activation lies, so this
program explains only a small share of its variance.
"""

READS = ()

REQUIRE = {
    "require", "requires", "required", "requiring", "requirement", "requirements",
    "need", "needs", "needed", "demand", "demands", "must", "take", "takes", "took",
}
MEASURE = {
    "much", "many", "more", "less", "few", "little", "amount", "number", "total", "size",
    "length", "weight", "distance", "time", "days", "period", "energy", "too", "small",
    "large", "big", "high", "low", "higher", "long", "short", "cost", "costs", "effort",
    "extra", "lot", "deal",
}
CUE = {
    "need", "needs", "needed", "require", "requires", "required", "take", "takes", "took",
    "without", "number", "total", "how", "much", "many", "length", "size", "time", "amount",
    "cost", "distance", "weight",
}
NECESSARY = {"has", "have", "had", "got", "hard", "easy", "harder", "easier"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    value = 0.0
    if word in REQUIRE:
        value -= 2.0
    if word in MEASURE:
        value -= 0.8
    same_doc = len(prefix.document_ids) > 1
    same_doc = same_doc and prefix.document_ids[-2] == prefix.document_ids[-1]
    if same_doc:
        before = prefix.token_strings[-2].strip().lower()
        if before in CUE:
            value -= 0.5
        if word == "to" and before in NECESSARY:
            value -= 2.0
    return carry, value

"""Predicts layers.15.mlp.down_proj:229, a diffuse MLP feature with rare strong negative bursts.

The activation is mostly small (std about 0.9), with occasional large negative values. The
negative side sits on the words of an unfinished noun phrase, before its head noun comes.
Strongest: a relational adjective (WordNet "adj.pert", e.g. "political", "administrative",
"territorial") right after "the/a/an", averaging about -1.3. Other words in the three places
after an article are weaker, fading with distance. "and"/"or", command-line dashes ("grep -B")
and bare spaces are mildly negative. Everything else is near zero.

The program adds these signed values. On eval its predictions correlate with the activation
(r = 0.11) and explain about 1% of its variance. A per-token lookup table would roughly triple
that on held-out data, but it would be an arbitrary word list, so it is left out.
"""

import wordnet

READS = ()

ARTICLES = {"the", "a", "an"}
CONJUNCTIONS = {"and", "or"}
# Words that end a noun phrase or start a new clause: they reset the article count.
BREAKS = set(".,;:!?()[]{}\"'`\n")


def _word(token_string):
    return token_string.strip().lower()


def _is_relational_adjective(word):
    # WordNet "pertainym" adjectives: 'administrative', 'political', 'medical', 'territorial'.
    return word.isalpha() and "adj.pert" in wordnet.categories(word)


def _is_adjective(word):
    return word.isalpha() and "adjective" in wordnet.parts_of_speech(word)


def step(carry, prefix, upstream):
    # carry: how many tokens since the last article in this noun phrase (None: no article).
    tok = prefix.token_strings[-1]
    word = _word(tok)
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    if not same_doc:
        carry = None
    since = None if carry is None else carry + 1
    if since is not None and (word in BREAKS or tok.strip() == ""):
        since = None
    value = 0.0
    if since is not None and since <= 3:
        value -= {1: 0.31, 2: 0.22, 3: 0.11}[since]
    if since == 1 and _is_relational_adjective(word):
        value -= 1.04
    elif _is_relational_adjective(word):
        value -= 0.31
    elif since == 1 and _is_adjective(word):
        value -= 0.23
    if word in CONJUNCTIONS:
        value -= 0.16
    if word.startswith("-") and word != "-":
        value -= 0.19
    if tok == " ":
        value -= 0.13
    new_carry = 0 if word in ARTICLES else since
    return new_carry, float(value)

"""Layer 15 MLP down_proj, component 231: a weak, diffuse readout.

Its activation is a dense linear readout of the MLP's hidden state. Nothing
simple explains most of it: token identity, repetition and position explain
under 1% of its variance (std ~0.28 around a mean of about -0.07). What is
visible:
  * the first token of each document reads exactly ~0, and the second reads
    higher (about +0.12), then it settles to its mean;
  * the typical level depends a little on the kind of the token being
    predicted: newlines are lower, spaces and punctuation somewhat lower,
    words and digits near the mean.

This program predicts those levels, from the document-relative position and
the character class of the newest token only.
"""

import re

READS = ()

REST = {"newline": -0.15, "space": -0.09, "punct": -0.10, "digit": -0.05,
        "cjk": -0.05, "word_space": -0.06, "word": -0.08, "other": -0.076}


def kind(s):
    if "\n" in s:
        return "newline"
    if not s.strip():
        return "space"
    if s.strip().isdigit():
        return "digit"
    if re.search(r"[一-鿿]", s):
        return "cjk"
    if re.fullmatch(r"\s?[^\w\s]+", s):
        return "punct"
    if re.fullmatch(r"\s?\w+", s):
        return "word_space" if s[0] == " " else "word"
    return "other"


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        index = 0  # first token of a document
    else:
        index = carry[1] + 1
    if index == 0:
        value = 0.0
    elif index == 1:
        value = 0.12
    else:
        value = REST[kind(prefix.token_strings[-1])]
    return (doc, index), value

"""Token-level guess for layers.15.mlp.down_proj component 233.

This component reads mostly one MLP hidden unit of layer 15, so its activation is a
lexical signal: it is set by the current word, hardly by context. It is negative
(often strongly) on a few word families and mildly positive on others:

- the short words "an", "am", "on", "can" (and "main", "min", "ann"): the strongest;
- words about beginnings and ends: start, starting, began, begin, beginning,
  initial, original, first, second, end, final;
- words of scope: main, central, whole, full, entire, total, general, standard,
  normal, national, both, all, long, short, basic;
- place and time prepositions and conjunctions: along, down, between, at, when,
  then, while, across, among, around;
- words whose final sound is a nasal (n, m, ng: "...ian", "...man", Chinese 中 / 年 /
  安, Korean 안, Cyrillic ан), mildly negative; words ending in l are weaker still;
- the digit 1 (negative), the digits 4, 5, 6 (mildly positive);
- Latin words ending in a vowel letter (mildly positive).

Everything else is 0, close to the component's typical value. Only the current token
is read, so the program needs no carry.
"""

import pypinyin
import regex

READS = ()

# The strongest negatives: the short "an"/"on" family.
AN_WORDS = {"an", "am", "on", "can", "ann", "main", "min"}
# Beginnings and ends of things.
BEGIN_WORDS = {
    "start", "starting", "started", "starts", "begin", "beginning", "began", "begun",
    "begins", "initial", "original", "first", "second", "end", "final",
}
# Words of scope and quantity that open a noun phrase.
SCOPE_WORDS = {
    "central", "whole", "full", "entire", "total", "general", "standard", "normal",
    "national", "both", "all", "long", "short", "basic",
}
# Place and time prepositions and conjunctions.
PREP_WORDS = {"along", "down", "between", "when", "then", "while", "across", "among", "around", "at"}
VOWEL_LETTERS = "aeiouy"
# Final nasal letters of scripts other than Latin: Cyrillic, Greek, Arabic, katakana.
NASAL_LETTERS = set("нмνμنمン")


def ends_in_nasal(word):
    """True if the word's last sound is a nasal (n, m, ng), in any script we can read."""
    last = word[-1]
    if word.isascii():
        return word.endswith("ng") or last in "nm"
    if last in NASAL_LETTERS or last in "んㄴ":
        return True
    if "가" <= last <= "힣":  # Hangul syllable: final consonant ㄴ, ㅁ or ㅇ
        return (ord(last) - 0xAC00) % 28 in (4, 16, 21)
    if regex.match(r"\p{Script=Han}", last):  # Chinese: its pinyin ends in -n or -ng
        reading = pypinyin.lazy_pinyin(last)[0]
        return reading.endswith("n") or reading.endswith("ng")
    return False


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if not word:
        return carry, 0.0
    if word in AN_WORDS:
        value = -3.5
    elif word == "1":
        value = -0.85
    elif word in ("4", "5", "6"):
        value = 0.5
    elif word in BEGIN_WORDS:
        value = -3.0
    elif word in SCOPE_WORDS:
        value = -2.0
    elif word in PREP_WORDS:
        value = -1.5
    elif ends_in_nasal(word):
        value = -0.9
    elif word.isascii() and word.isalpha() and word[-1] == "l":
        value = -0.6  # the liquid "l" is a weaker sonorant ending
    elif word.isascii() and word.isalpha() and word[-1] in VOWEL_LETTERS:
        value = 0.2
    else:
        value = 0.0
    return carry, float(value)

"""Layer 15 MLP down_proj, hidden unit 239: a word-class detector for the slot that
completes a verb or prepositional phrase.

The unit reads the MLP's hidden state. Its activation is largest on
  * object pronouns and pro-forms that finish a phrase after a verb, preposition,
    "to" or a subject pronoun ("do it", "about it", "want them", "do so", "for you"),
  * the infinitive "to" ("want to", "how to", "need to"),
  * auxiliaries do/be/have/not after "to" or a subject ("to do", "they are"),
  * verbs right after a subject pronoun ("you know", "I do").
It is near zero on most other words, and slightly negative on digits, punctuation and spacing.
This program reproduces that with a few word classes and one value per class.
"""
from functools import lru_cache

import wordnet

READS = ()

OBJECT_PRONOUNS = {
    "it", "them", "him", "us", "me", "you", "this", "that", "these", "those",
    "so", "here", "there", "too", "anything", "everything", "something", "nothing", "anymore",
}
AUXILIARIES = {"do", "did", "does", "be", "been", "being", "have", "has", "had", "not", "is", "are", "was", "were"}
PREPOSITIONS = {"of", "for", "with", "about", "on", "at", "by", "into", "like", "from", "in", "over", "without", "than"}
SUBJECT_PRONOUNS = {"i", "you", "he", "she", "we", "they", "it"}
FUNCTION_WORDS = {"the", "a", "an", "and", "or", "but"}

VALUES = {"pronoun_after_head": 1.4, "pronoun_other": 0.5, "to": 0.9, "aux_after_head": 0.9,
          "aux_other": 0.4, "verb_after_subject": 0.5, "function": 0.2, "punct": -0.05, "other": 0.0}


@lru_cache(maxsize=None)
def is_verb(word):
    return word.isalpha() and "verb" in wordnet.parts_of_speech(word)


def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    word = prefix.token_strings[-1].strip().lower()
    before = prefix.token_strings[-2].strip().lower()
    after_head = before in PREPOSITIONS or before == "to" or before in SUBJECT_PRONOUNS or is_verb(before)
    if word in OBJECT_PRONOUNS:
        key = "pronoun_after_head" if after_head else "pronoun_other"
    elif word == "to":
        key = "to"
    elif word in AUXILIARIES:
        key = "aux_after_head" if after_head else "aux_other"
    elif before in SUBJECT_PRONOUNS and is_verb(word):
        key = "verb_after_subject"
    elif word in FUNCTION_WORDS:
        key = "function"
    elif not any(ch.isalnum() for ch in word):
        key = "punct"
    else:
        key = "other"
    return None, VALUES[key]

"""Clause subjects, weakly: a word-class rule for layers.15.mlp.down_proj unit 246.

The component's output direction promotes modal verbs next ("will", "would", "must",
"has"). Its activation is high on the word that ends the subject of a clause, before
the verb: subject pronouns ("it", "they") and nouns after a determiner ("the Court",
"this problem") when a clause opens just before them. It is negative on words that
join or open clauses ("that", "so", "but", "which", "where").

This is a weak fit: the rule explains about 3% of the variance on held-out eval rows
(Pearson r about 0.17). Most of the activation's spread is not predictable from the
words so far, even with a full lookup of nearby words.

The rule reads only the words so far: the current word, the one before it and the one
before that. A word is a noun by WordNet. A clause opens at punctuation, at a joining
word, or at the start of a document. Values are the mean activations per class, measured
on 131k tokens of training text.
"""

import wordnet

READS = ()

SUBJECT_PRONOUNS = {"it", "they", "he", "she", "we", "i", "you"}
DETERMINERS = {"the", "a", "an", "this", "that", "these", "those", "his", "her", "their",
               "its", "my", "our", "your", "each", "every", "some", "any", "such"}
JOINERS = {"that", "if", "when", "where", "so", "since", "but", "and", "or", "because",
           "although", "though", "while", "as", "once", "until", "which", "who", "how",
           "what", "unless", "whether", "then", "thus", "however", "therefore"}
PUNCTUATION = set(",.;:!?\"()-\n")
CLAUSE_OPENERS = JOINERS | PUNCTUATION | {"<start>"}


def is_noun(word):
    return word.isalpha() and "noun" in wordnet.parts_of_speech(word)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    doc = prefix.document_ids[-1]
    if carry is None or carry[2] != doc:
        last, before = "<start>", "<start>"
    else:
        last, before = carry[0], carry[1]
    if word in SUBJECT_PRONOUNS and last in CLAUSE_OPENERS:
        value = 0.65  # subject pronoun opening a clause
    elif is_noun(word) and last in DETERMINERS and before in CLAUSE_OPENERS:
        value = 0.8  # subject noun phrase head, after a clause opener
    elif is_noun(word) and last in DETERMINERS:
        value = 0.2
    elif is_noun(word) and last in CLAUSE_OPENERS:
        value = 0.1  # bare subject noun, as in "Apple is"
    elif is_noun(word):
        value = 0.14
    elif word == "that":
        value = -0.45
    elif word in JOINERS:
        value = -0.17
    elif word in PUNCTUATION:
        value = -0.01
    else:
        value = 0.07
    return (word, last, doc), value

"""Layer 15 MLP hidden unit 254, read out by down_proj component 254.

The component's input direction is mostly MLP hidden unit 254 of layer 15 (about 0.55 of its
0.89 norm), so its activation is about 0.38 times that unit's value. That unit is dense and
context-driven: its sign is mixed, and most of its size comes from contexts that no short
rule captures. This program keeps only the few tendencies seen in sampled text:

- a small baseline above zero;
- "of" and "in" lean negative (about -0.09): they often sit mid-phrase ("top of", "in the");
- "and", "to", "the", "with" lean slightly positive (about +0.02);
- a number lean negative, and so does the token right after a number;
- measure words after a number (years, months, dollars, km ...) lean positive;
- the first token of each document is 0, as it is in the data.

It reads only the newest two tokens and the document boundary. Its explained variance on
eval rows is about 0.2% (r about 0.04), so it captures almost none of the component's
activation; the signal is in the hidden state, not in the words.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

BASELINE = 0.024
NEGATIVE_WORDS = {" of", " in"}
POSITIVE_WORDS = {" and", " to", " the", " with"}
MEASURE_WORDS = {
    " years", " months", " days", " weeks", " hours", " minutes",
    " dollars", " words", " km", " kg", " percent",
}


def is_number(text: str) -> bool:
    return text.strip().isdigit()


def step(carry, prefix, upstream: Mapping):
    t = prefix.position
    if t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2]
    value = BASELINE
    if cur in NEGATIVE_WORDS:
        value -= 0.09
    if cur in POSITIVE_WORDS:
        value += 0.024
    if is_number(cur):
        value -= 0.031
    if is_number(prev):
        value -= 0.028
    if cur in MEASURE_WORDS:
        value += 0.107
    return carry, float(value)

"""Layer-15 MLP down-projection component 255: a sparse, signed "conditional word" feature.

Plain-terms summary. The component's activation is near zero noise on almost every token.
It is large on a few word types and the sign depends on the words around them:

* Conditional openers " if", " If", " When" lean positive. They are strongly positive when the
  clause follows wording about expected behaviour or editing files and commands ("make sure",
  "expected", "edit", "again", "file", "command", "they"). They are weakly negative in code
  or in hedged advice ("return", "else", "null", "however", "especially", "based").
* Comparison operators and exception words lean negative: ">", ">=", "<", "!=", "than",
  "unless", "too", "?".
* A few quantifier and time words lean mildly positive: "any", "anyone", "never", "still", "all".

Everything else is predicted as 0. This is a readable approximation of the component's
largest responses; it does not reproduce the low-level noise that makes up most of its variance.
"""

READS = ()

CONTEXT_UP = {"sure", "expected", "edit", "again", "file", "command", "they", "make"}
CONTEXT_DOWN = {"return", "else", "null", "however", "especially", "based", "testing", "services"}

VALUES = {
    " any": 0.28, " anyone": 0.58, " never": 0.35, " still": 0.26, " all": 0.2,
    " >": -0.84, " >=": -1.5, " <": -0.31, " !=": -0.45, "?": -0.6,
    " than": -0.33, " unless": -0.9, " too": -0.45,
}


def conditional_value(prefix):
    """Activation predicted for a conditional opener, from the words in the same clause."""
    n = len(prefix.token_ids)
    words = []
    for i in range(max(0, n - 13), n - 1):
        if prefix.document_ids[i] == prefix.document_ids[-1]:
            words.append(prefix.token_strings[i].strip().lower())
    value = 0.4
    if CONTEXT_UP & set(words):
        value += 2.5
    if CONTEXT_DOWN & set(words):
        value -= 1.0
    return value


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in (" if", " If", "If", " When"):
        return carry, conditional_value(prefix)
    return carry, VALUES.get(tok, 0.0)
